const ledger = 'd06-conversion-ledger', storage = 'd06-rack-migration';
const control = (key,label,options) => ({ key,label,options });
export const learningContract = Object.freeze({
  driving_question: 'How does power get from a rack inlet to a fast-changing low-voltage chip load?',
  fixed_boundary: 'Named rack hardware is separated from explicitly hypothetical board and storage calculations.',
  changed_variable: 'Input plane, final-loop resistance, regulator phase count, source response or buffer recharge interval.',
  primary_payoff: 'Locate conversion, distribution and stored energy at the physical boundary that needs them.',
  misconception: 'A rack bus is 800 V, every PSU is three-phase, one battery backs every rack, or remote stored energy makes local regulation unnecessary.',
  closing_question: 'Which limit prevents this buffer from supporting a repeated compute burst?'
});
export const initialState = Object.freeze({ resistance:100, phases:4, location:'board', response:0.2, failed:0, rest:10, reveal:false });
export const scenes = Object.freeze([
 {id:'rack-power-path',label:'Shelf to silicon',title:'Rack power crosses a busbar before board regulators feed the chips.',reference:ledger,pedagogical_role:'problem',boundary:'Functional path · rack voltage from NVIDIA DGX guide · board stages vary by platform.',explanation:['The power shelf contains the power supply units (PSUs). Their DC output feeds a conductive busbar along the rack, which supplies compute and switch trays. Within a tray, power distribution and protection feed converters and local regulators. A busbar carries power; it does not change voltage.','The NVIDIA guide identifies a nominal 50–51 V in-rack bus. The remaining stages here show functions, not an unpublished GB300 board schematic. A point-of-load regulator maintains a device rail; it is not the same object as a rack PSU.']},
 {id:'rear-busbar',label:'See the rack bus',title:'The DGX GB300 power busbar runs behind the trays.',reference:ledger,pedagogical_role:'architecture',boundary:'NVIDIA DGX GB300 rear hardware figure · nominal 50–51 V DC in-rack bus.',explanation:['NVIDIA’s annotated rear view locates the power busbar, cooling manifolds and NVLink cable cartridges. They serve different paths. The compact version enlarges the rear cabinet and points to the same busbar location as the manufacturer figure.','The voltage here belongs to the local rack distribution bus, not the separate 800 V hall architecture. This manufacturer figure depicts DGX GB300; it does not establish every OEM GB300 rack’s mechanical arrangement.']},
 {id:'psu-input',label:'Shelf versus PSU',title:'A three-phase shelf can feed single-phase PSU modules.',reference:ledger,pedagogical_role:'mechanism',boundary:'Example: Advanced Energy ORv3 3 kW PSU · 480/277 V wye supply · not a GB300 wiring diagram.',explanation:['A 480/277 V wye supply has 480 V RMS between live phases and approximately 277 V from a phase to neutral. Neutral is not a fourth phase and protective earth is separate. The shelf can distribute its three phases across single-phase PSU modules.','Advanced Energy’s ORv3 3 kW PSU specifies nominal 200–277 V single-phase input and 50 V DC output. The six-module shelf accepts several input arrangements. This verifies the component-versus-system distinction; it does not identify the precise PSU installed by each NVL72 vendor. The drawing omits protection and earth, and is not wiring guidance.']},
 {id:'board-rails',label:'Intermediate and core rails',title:'An intermediate converter and a local regulator can split the voltage reduction.',reference:ledger,pedagogical_role:'mechanism',boundary:'Illustrative 48 → 12 → 1 V chain · TI TIDA-050095 verifies the intermediate-converter category, not this entire board.',explanation:['An intermediate bus converter (IBC) can create a lower bus rail before point-of-load voltage regulator modules (VRMs) feed compute cores. Other board loads can branch to their own converters. The branch rails and the number of stages are platform-specific.','TI’s 48-to-12-V, 2 kW TIDA-050095 reference is a transformer-less regulated buck converter. DC/DC names a conversion function, not a requirement to contain a transformer. Direct, two-stage and other intermediate-voltage architectures exist; the course does not assume every GPU takes 54 V directly into its last buck stage.']},
 {id:'local-current',label:'The final current path',title:'At 1 V, a small path resistance can consume a large share of the voltage.',reference:ledger,pedagogical_role:'comparison',boundary:'Illustrative 1 kW core at 1 V · fixed delivered core power · lossless upstream conversion for the current comparison.',controls:[control('resistance','Core-path loop',[[100,'100 µΩ'],[10,'10 µΩ']])],explanation:['For the same ideal 1 kW, current is 20 A at 50 V and 1,000 A at 1 V. Current is local to each voltage plane; these are not 1,000 A flowing all the way from the power shelf. Actual upstream power also includes conversion and distribution loss.','At 1,000 A a stipulated 100 microohm loop dissipates I²R = 100 W and drops IR = 0.1 V. Reducing it to 10 microohms gives 10 W and 0.01 V. This explains why the high-current route near the die must be short and low impedance. It is not a board design or permitted core-voltage tolerance. Vertical rack distribution is distinct from vertical power delivery at a chip package.']},
 {id:'multiphase',label:'Stagger the switching',title:'Interleaving regulator phases reduces their combined current ripple.',reference:ledger,pedagogical_role:'mechanism',boundary:'Normalized triangular teaching currents · 1,000 A average total · fixed 30% duty ratio · not a GB300 waveform.',controls:[control('phases','Converter phases',[[1,'One'],[4,'Four']])],explanation:['Each converter phase is a switched power path with an inductor. Its current rises and falls. Staggering the paths makes part of one phase’s rising ripple coincide with another’s falling ripple before their currents sum. The total average is held fixed while each phase carries a share.','Output capacitors supply the remaining difference from the load and feedback maintains the voltage rail. Ripple is reduced, not eliminated. These high-frequency converter phases are distinct from the facility’s three-phase AC. The normalized traces do not select inductance, switching frequency, compensation or a real regulator design.']},
 {id:'energy-locality',label:'Where energy connects',title:'Stored energy supports the loads reached through its electrical path.',reference:storage,pedagogical_role:'architecture',boundary:'Functional electrical scopes · no universal response-time bands or installed BBU count.',controls:[control('location','Stored energy',[['board','Board capacitors'],['rack','Rack BBU'],['facility','Facility storage']])],explanation:['Local capacitors have a short current loop to the devices. A rack battery backup unit (BBU) supports its qualified DC bus through a controlled converter. Facility UPS batteries or BESS connect farther upstream and may support a broader load set. Trace forward and return paths, protection and conversions; physical distance alone is not the whole response model.','Path resistance gives IR drop and inductance opposes a changing current through L di/dt. A large distant battery cannot eliminate the need for chip decoupling. A rack BBU does not, merely by powering the rack bus, power the facility pumps or remote networking. The connection and controls determine what continues operating.']},
 {id:'source-handoff',label:'Overlapping contributions',title:'The buffer supplies the difference while the upstream source ramps.',reference:storage,pedagogical_role:'balance',boundary:'Original bus model · +40 kW load step · source ramps linearly · losses and electrical transients excluded.',controls:[control('response','Source response',[[0.2,'0.2 seconds'],[0.4,'0.4 seconds']])],explanation:['The load rises instantly in this teaching model while the additional source power rises linearly from zero to 40 kW. The local buffer supplies the declining difference. The source and buffer contributions overlap; there is no fixed moment when an empty capacitor hands all power to a battery.','Required buffer energy is the area between the curves: one half times the 40 kW initial deficit times the response duration. The initial buffer power remains 40 kW when response time doubles, but its delivered energy doubles. Real behavior also needs permitted voltage range, capacitance, resistance, inductance and converter limits. Even with an already-running online-UPS inverter, DC-link and downstream regulation have finite dynamics.']},
 {id:'bbu-shelf',label:'Count modules and capacity',title:'A six-module BBU shelf can preserve 15 kW after one module fails.',reference:storage,pedagogical_role:'comparison',boundary:'Specific ORv3 example · six 3 kW modules, 5+1 · 15 kW protected load · source timing/state conditions apply.',controls:[control('failed','Unavailable modules',[[0,'None'],[1,'One'],[2,'Two']])],explanation:['Analog Devices describes an ORv3 shelf with six BBU modules in a 5+1 configuration. The reviewed OCP module specification requires 3 kW discharge and at least 240 seconds under declared cell-state, temperature and aging conditions. Five surviving modules supply the 15 kW load; four have only 12 kW.','This is a power-capacity screen, not a simulation of fault isolation or a guaranteed runtime at arbitrary state of charge. BBU can mean a module or a shelf, so say which. NVL72 does not prescribe one BBU per rack, and this 15 kW example is not sized for the GB300 rack. The OCP specification has nonzero activation/ramp timing and a separately controlled peak-shaving mode.']},
 {id:'buffer-recharge',label:'Pay back each burst',title:'A buffer can repeat a compute burst only if it can recharge between bursts.',reference:storage,pedagogical_role:'counterexample',boundary:'Original DC-bus model · 120 kW source cap · 110 kW between bursts · 160 kW for 0.2 s · ideal storage.',controls:[control('rest','Time between bursts',[[10,'10 seconds'],[0.2,'0.2 seconds']])],explanation:['The buffer supplies 160 − 120 = 40 kW for 0.2 s, delivering 8 kJ. During a 110 kW interval the 120 kW source has 10 kW left for recharge, so an ideal refill needs 0.8 s. A ten-second gap is sufficient.','A 0.2-second gap replenishes only 2 kJ, leaving 6 kJ unrecovered each cycle. Average load is then 135 kW, above the 120 kW source. More storage delays depletion but cannot sustain that average indefinitely. Real losses, charge limits, cycle life and reserved outage energy tighten the constraint further.']},
 {id:'rack-transfer',label:'Choose the limiting fix',title:'Would a larger battery sustain the rapid burst pattern indefinitely?',reference:storage,pedagogical_role:'transfer',boundary:'Same rapid pattern: 160 kW for 0.2 s, 110 kW for 0.2 s · source cap 120 kW.',reveal:'reveal',explanation:['Predict before revealing. The repeated pattern averages 135 kW while the source provides at most 120 kW. The buffer loses 6 kJ every 0.4-second cycle under the stated ideal schedule. A larger battery stores more cycles, but eventually depletes.','Change the sustained power balance: lengthen the interval between bursts, reduce demand, add source capacity, or accept finite runtime. After that, separately check buffer peak power, usable energy, voltage limits, recharge controls and the loads protected during an outage. Continue to the 800 V comparison with the local rack bus and final device rails now distinct.']}
]);
